+function getMochaTestPath(runnable) {
+  const path = [];
+  let node;
+  if (runnable.type === 'hook') { node = runnable.ctx.currentTest; } else { node = runnable; }
+  while (node && node.parent) {
+    if (node.title) path.push(node.title);
+    node = node.parent;
+  }
+  return path.reverse();
+}
